\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}

\title{Compactness in Metric Spaces: Reading Notes}
\author{Analysis Reading Group}
\date{Winter 2026}

\begin{document}
\maketitle

\section{Preliminaries}
Throughout, $(X,d)$ is a metric space and ``compact'' means
compact by open covers. We record the elementary facts we
need before turning to the main equivalence.

\begin{lemma}\label{lem:finite}
Every finite subset of a metric space is compact.
\end{lemma}

\begin{proof}
An open cover of a finite set admits the subcover that keeps,
for each point, one chosen member of the cover; finitely many
points need only finitely many members.
\end{proof}

Lemma~\ref{lem:finite} is of course immediate from the
definition, but isolating it keeps the later counting
arguments honest.

\begin{lemma}\label{lem:closed}
A closed subset of a compact metric space is compact.
\end{lemma}

\begin{proof}
Adjoin the complement of the subset to any open cover of it;
the result covers the whole space, so a finite subcover
exists, and discarding the complement leaves a finite cover
of the subset.
\end{proof}

\section{The main equivalence}

\begin{theorem}\label{thm:main}
A metric space is compact if and only if it is complete and
totally bounded.
\end{theorem}

\begin{proof}
For the forward direction, total boundedness follows by
covering $X$ with finitely many balls of each fixed radius,
and completeness follows because a Cauchy sequence with a
convergent subsequence converges. For the converse, one
extracts from any sequence of approximating centres a Cauchy
subsequence and passes to its limit. Where a fixed closed
piece $F$ of a compact ambient space $K$ is needed,
Lemma~\ref{lem:closed} applied to $K \cap F$ supplies the
required compactness.
\end{proof}

\begin{lemma}\label{lem:seq}
Every sequence in a compact metric space has a convergent
subsequence.
\end{lemma}

\begin{proof}
If the range of the sequence is finite, some value repeats
and the constant subsequence converges. Otherwise the range
is infinite, and total boundedness lets one thin the sequence
step by step so that successive terms lie in balls of radius
$2^{-n}$; the thinned sequence is Cauchy, hence convergent by
completeness.
\end{proof}

\begin{corollary}\label{cor:max}
A continuous real-valued function on a compact metric space
attains its maximum and its minimum.
\end{corollary}

\begin{proof}
The image is compact in $\mathbb{R}$, hence closed and
bounded, and a closed bounded set of reals contains its
supremum and its infimum.
\end{proof}

\section{Where this leaves us}
Combining Lemma~\ref{lem:seq} with Lemma~\ref{lem:closed}
yields the sequential reformulation of compactness for closed
subsets, and Corollary~\ref{cor:max} is the form in which
most of us will actually use compactness. The reading group
will take up the non-metric counterexamples next week.
\end{document}

